using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class GoalTurnChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void VerifyModel(){var old=JsonUtility.FromJson<WorldPlayMemory>("{}");Require(old.Valid()&&old.Goals.sharedRounds==0,"Historical save rejected");var m=new GoalMemory{sharedRounds=3,sharedEnjoyment=.6f};Require(JsonUtility.FromJson<GoalMemory>(JsonUtility.ToJson(m)).Valid(),"Shared round memory rejected");m.sharedRounds=-1;Require(!m.Valid(),"Negative rounds accepted");m.sharedRounds=3;m.sharedEnjoyment=float.NaN;Require(!m.Valid(),"Invalid shared enjoyment accepted");Debug.Log("BWVR_GOAL_TURNS_MODEL_PASS: historical/default and bounded shared memories");}
 public static void Verify(Action<BeachBall,BallGoal> capture=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var god=slice.GetComponentInChildren<CreatureHybrid>();var ball=slice.GetComponentInChildren<BeachBall>();var course=ball.Goals;var game=course.Turns;var gate=course.Gates[0];var lane=ball.Bowling;var nav=god.GetComponent<IslandNavigator>();float unit=nav.world.Scale;
  var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release objects first");var godAt=god.transform.position;var godRotation=god.transform.rotation;var people=slice.GetComponentsInChildren<VillagerSocial>();var points=people.Select(p=>p.transform.position).ToArray();var poses=course.Gates.Select(g=>g.transform.position).ToArray();var rotations=course.Gates.Select(g=>g.transform.rotation).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();
  var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f,playPreference=1};test.WorldPlay.Goals.preference=1;
  void Cancel(){game.Cancel("QA reset");god.Interrupt("Turn QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();}ball.ReturnHome();}
  void Step(bool ai=false){if(ai)god.Tick(.05f);else test.Hybrid.time+=.05f;ball.Advance(.05f,test.paused);}
  bool Pointer(bool pressed=true,bool was=false,bool tracked=true,int side=1)=>(bool)typeof(QuestSlice).GetMethod("GoalChallengePointer",Flags).Invoke(slice,new object[]{side,pressed,was,gate.GetComponentInChildren<GoalChallengeKey>().GetComponent<Collider>(),tracked});
  void Observe(){god.transform.LookAt(gate.transform.position);Physics.SyncTransforms();}
  try{
   Cancel();field.SetValue(slice,test);god.NewSeason();ball.ResetWorld();foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var p in people)p.transform.position+=Vector3.right*unit*300;foreach(var a in cooldowns.Keys)if(a!=ball.GetComponent<CreatureAffordance>())a.cooldown=10000;foreach(var pin in lane.Pins)pin.GetComponent<Collider>().enabled=false;gate.transform.rotation=Quaternion.LookRotation(lane.Forward);Require(gate.Place(lane.Target),"No flat challenge site");god.transform.position=nav.world.ProjectFoot(lane.Start-lane.Right*12*unit,nav.profile);nav.ResetRoute();Observe();for(int i=0;i<12;i++)Step();
   var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);
   var key=gate.GetComponentInChildren<GoalChallengeKey>();var ray=new Ray(key.transform.position+gate.transform.forward*unit*4,-gate.transform.forward);Require(Physics.Raycast(ray,out var hit,unit*8)&&hit.collider==key.GetComponent<Collider>(),"Challenge badge cannot be pointed at");Pointer(true,false,false);Pointer(true,true);Pointer(true,false,true,0);Require(!game.Active,"Untracked/held/left input activated game");test.paused=true;Pointer();Require(!game.Active,"Paused invitation accepted");test.paused=false;slice.SetSanctuaryOpen(true);Pointer();Require(!game.Active,"Menu invitation accepted");slice.SetSanctuaryOpen(false);palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Pointer();Require(game.Current==GoalTurns.Phase.PlayerTurn,"Native invitation failed");Pointer(true,true);Require(game.Active,"Held trigger canceled invitation");
   for(int round=0;round<3;round++){
    Require(game.Current==GoalTurns.Phase.PlayerTurn&&game.Round==round,"Wrong player round");var origin=round==0?lane.Start:game.Origin;if(round==0)ball.PlaceOnGround(origin,true);Observe();for(int i=0;i<12;i++)Step();Require(!ball.GetComponent<CreatureAffordance>().Available,"Creature can take player's turn");
    Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,ball.GetComponent<CarryItem>()}),"Native player pickup failed");var motion=(ThrowMotion[])typeof(QuestSlice).GetField("throwMotion",Flags).GetValue(slice);var rig=(Transform)typeof(QuestSlice).GetField("rig",Flags).GetValue(slice);for(int i=0;i<4;i++)motion[1].Sample(origin+lane.Forward*i*.02f*rig.localScale.x,i*.02f,rig.localScale.x);typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(origin,lane.Forward)});Require(game.Current==GoalTurns.Phase.PlayerFlight,"Native throw did not start player turn: "+game.LastReason);
    for(int i=0;i<300&&game.Current==GoalTurns.Phase.PlayerFlight;i++)Step();Require(game.Current==GoalTurns.Phase.PrepareCreature&&ball.FetchReserved,"Player outcome did not invite a physical return: "+game.Current+" "+game.LastReason);
    var at=ball.Body.position;test.paused=true;ball.Advance(10,true);Require(game.Current==GoalTurns.Phase.PrepareCreature&&ball.Body.position==at,"Pause advanced shared return");test.paused=false;
    string trace="";var previousPhase=god.GetComponent<CreatureCuriosity>().Current;bool carriedBefore=false,creatureShot=false,carriedAfter=false;for(int i=0;i<6500&&game.Active&&game.Round==round;i++){if(game.Current==GoalTurns.Phase.CreatureTurn&&god.GetComponent<CreatureCuriosity>().Current==CreatureCuriosity.Phase.Rest){Require(course.Plan(god.transform.position)==gate,"Returned ball has no feasible remembered goal: "+nav.world.ToNav(god.transform.position));int seed=1;while((CreatureDecisionModel.Variation(seed,god.State.decisions,CreatureAction.PlayWithToy,"goal")+1)*.5f>.7f)seed++;god.State.seed=seed;}Step(true);var phase=god.GetComponent<CreatureCuriosity>().Current;if(phase!=previousPhase){trace+=" / "+phase+" t="+test.Hybrid.time+" god="+nav.world.ToNav(god.transform.position)+" ball="+ball.Body.position+" blocked="+nav.Blocked+" game="+game.Current;previousPhase=phase;}carriedBefore|=game.Current==GoalTurns.Phase.PrepareCreature&&god.GetComponent<CreatureCuriosity>().Holding==ball.GetComponent<CarryItem>();creatureShot|=game.Current==GoalTurns.Phase.CreatureFlight;carriedAfter|=game.Current==GoalTurns.Phase.ReturnToPlayer&&god.GetComponent<CreatureCuriosity>().Holding==ball.GetComponent<CarryItem>();}
    Require(game.Round==round+1&&carriedBefore&&creatureShot&&carriedAfter,"Incomplete autonomous round "+round+": "+game.Current+" / "+game.LastReason+" / "+god.Explanation+" trace "+trace+" / "+string.Join(" | ",god.Journal.Capture().Select(e=>e.kind+":"+e.reason)));
    Require(Vector3.Distance(ball.transform.position,game.Origin+Vector3.up*ball.Radius*unit)<unit*1.2f,"Ball did not return to player's circle");Require(test.WorldPlay.fetchReturns==0&&!ball.JustFetched,"Course return misattributed to ordinary fetch");if(round<2)Require(((LineRenderer)typeof(BeachBall).GetField("fetchRing",Flags).GetValue(ball)).enabled,"Player launch circle hidden between turns");if(round==0)capture?.Invoke(ball,gate);
   }
   Require(!game.Active&&game.Round==3&&test.WorldPlay.Goals.sharedRounds==3&&test.WorldPlay.Goals.sharedEnjoyment>.4f,"Three-round finish/memories missing");var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.WorldPlay.Goals.sharedRounds==3,"Shared round save invalid");int rounds=test.WorldPlay.Goals.sharedRounds;for(int i=0;i<40;i++)Step();Require(test.WorldPlay.Goals.sharedRounds==rounds,"Round counted twice");
   Pointer();Require(game.Active,"Repeat invitation failed");Pointer();Require(!game.Active,"Badge could not cancel invitation");Pointer();Require(game.Active,"Moved goal setup failed");gate.Place(gate.transform.position);Require(!game.Active&&!ball.FetchReserved,"Moving goal retained invitation");Pointer();Require(game.Active,"Expiry setup failed");for(int i=0;i<1820;i++)Step();Require(!game.Active&&test.WorldPlay.Goals.sharedRounds==rounds,"Expired invitation gained memory");Pointer();Require(game.Active,"Reload setup failed");field.SetValue(slice,saved);god.NewSeason();ball.ResetWorld();Require(!game.Active&&saved.WorldPlay.Goals.sharedRounds==rounds,"Reload restored stale live turn or lost completed memory");
   Debug.Log("BWVR_GOAL_TURNS_PLAY_PASS: physical badge and input isolation, three native player tosses, utility-selected carries/throws/returns, pause, exclusive turns, distinct fetch receipts, once-only shared memories, expiry, moved-goal cancellation and save/reload");
  }finally{foreach(var item in held)if(item!=null){item.held=false;item.GetComponent<Collider>().enabled=true;}held[0]=held[1]=null;Cancel();field.SetValue(slice,original);god.NewSeason();ball.ResetWorld();for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);foreach(var pin in lane.Pins)pin.GetComponent<Collider>().enabled=true;for(int i=0;i<3;i++){course.Gates[i].transform.SetPositionAndRotation(poses[i],rotations[i]);course.Gates[i].GetComponent<CarryItem>().home=poses[i];}foreach(var c in cooldowns)c.Key.cooldown=c.Value;god.transform.SetPositionAndRotation(godAt,godRotation);nav.ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.position=points[i];people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
